export function buildProductionQuestion(draft) {
  const letters=['A','B','C','D']; const key=letters[draft.correct]; const correct=draft.choices[draft.correct];
  const incorrect=draft.choices.flatMap((c,i)=>i===draft.correct?[]:[{letter:letters[i],text_en:c[2],text_th:c[3]}]);
  return {
    id:draft.id, dom:4, question:draft.stem[0], options:draft.choices.map(c=>c[0]), correct_idx:draft.correct,
    explanation:`Option ${key} is correct. ${correct[2]} ${incorrect.map(c=>`Option ${c.letter} is incorrect: ${c.text_en}`).join(' ')}`,
    short_explanation_en:draft.takeaway, question_th:draft.stem[1], options_th:draft.choices.map(c=>c[1]),
    explanation_th:`ข้อ ${key} ถูกต้อง: ${correct[3]}\n${incorrect.map(c=>`- ข้อ ${c.letter} ไม่ถูกต้อง: ${c.text_th}`).join('\n')}`,
    explanation_detail:{correct:{en:correct[2],th:correct[3]},incorrect}
  };
}
export const stagedQuestions=drafts.filter(d=>d.status!=='REJECTED').map(buildProductionQuestion);
export const acceptedQuestions=drafts.filter(d=>(d.status||reviewStatus)==='ACCEPTED').map(buildProductionQuestion);
export const reviewRecords=drafts.map(d=>({questionId:d.id,officialObjective:d.objective,secondaryObjectives:d.secondaryObjectives||[],outlineBullet:d.bullet,supportingBullets:d.supportingBullets||[],assessmentTargets:d.targets.map(t=>`D4-AT-${String(t).padStart(2,'0')}`),knowledgeIds:d.knowledge.map(k=>`KNOW-D4-${String(k).padStart(3,'0')}`),sourceReferences:d.sources,testedConcept:d.concept,assessedDecision:d.decision,type:d.type,academicQA:reviewStatus,bilingualQA:reviewStatus,status:d.status||reviewStatus,independentHumanReview:'not-claimed'}));
